SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.los, COUNT(pr.itemid) AS procedure_count, COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN p.subject_id END) AS mortality_count, COUNT(DISTINCT CASE WHEN p.dod IS NULL THEN p.subject_id END) AS survival_count, percent_rank() OVER (ORDER BY COUNT(pr.itemid)) AS procedure_percentile_rank FROM patients p JOIN icustays i ON p.subject_id = i.subject_id AND p.hadm_id = i.hadm_id JOIN procedureevents pr ON p.subject_id = pr.subject_id AND p.hadm_id = pr.hadm_id AND pr.charttime BETWEEN i.intime AND i.outtime WHERE p.gender = 'M' AND p.anchor_age BETWEEN 88 AND 98 AND i.first_careunit = 'ICU' AND i.stay_id IN (SELECT stay_id FROM admissions WHERE admission_type = 'Elective') AND pr.itemid IN (SELECT itemid FROM d_items WHERE category = 'Diagnostic') AND (pr.charttime - i.intime) <= 72 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.los ORDER BY procedure_percentile_rank NULLS LAST;